import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.BSaF8iZ6.js";const h=JSON.parse('{"title":"Seller Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/seller-quick-start.md","filePath":"getting-started/seller-quick-start.md","lastUpdated":1789411447000}'),s={name:"getting-started/seller-quick-start.md"};function n(l,e,i,d,c,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="seller-quick-start" tabindex="-1">Seller Quick Start <a class="header-anchor" href="#seller-quick-start" aria-label="Permalink to &quot;Seller Quick Start&quot;">​</a></h1><div class="page-roles"><span class="role role--seller">Seller</span></div><p>This page follows a new seller from sign-up to their first payout. Each step links to the page with the details.</p><h2 id="_1-create-your-seller-account" tabindex="-1">1. Create your seller account <a class="header-anchor" href="#_1-create-your-seller-account" aria-label="Permalink to &quot;1. Create your seller account&quot;">​</a></h2><p>Open the marketplace landing page from the store icon in the storefront header, and fill in the <strong>Become Seller</strong> form. See <a href="./../sellers/becoming-a-seller">Becoming a Seller</a>.</p><h2 id="_2-wait-for-approval-and-sign-in" tabindex="-1">2. Wait for approval and sign in <a class="header-anchor" href="#_2-wait-for-approval-and-sign-in" aria-label="Permalink to &quot;2. Wait for approval and sign in&quot;">​</a></h2><p>If the store approves new sellers, you can sign in at <strong>Seller Login</strong> once your account is approved. You&#39;ll get an email when that happens.</p><h2 id="_3-complete-your-profile" tabindex="-1">3. Complete your profile <a class="header-anchor" href="#_3-complete-your-profile" aria-label="Permalink to &quot;3. Complete your profile&quot;">​</a></h2><p>Add your phone number, business name and description, and your full address: address, city, state, postcode and country. You can&#39;t list products or use bulk upload until these are filled in. A logo, banner and policies are optional, but they help customers trust your shop. See <a href="./../seller-panel/manage-profile">Manage Profile</a>.</p><h2 id="_4-choose-a-plan" tabindex="-1">4. Choose a plan <a class="header-anchor" href="#_4-choose-a-plan" aria-label="Permalink to &quot;4. Choose a plan&quot;">​</a></h2><p>If the store uses subscription plans, choose one before you start selling. See <a href="./../subscriptions/choosing-a-plan">Choosing a Plan</a>.</p><h2 id="_5-add-your-products" tabindex="-1">5. Add your products <a class="header-anchor" href="#_5-add-your-products" aria-label="Permalink to &quot;5. Add your products&quot;">​</a></h2><ul><li>Create your own products. See <a href="./../catalog/product-management">Product Management</a>.</li><li>Sell products already in the store&#39;s catalog at your own price. See <a href="./../catalog/selling-existing-products">Selling Existing Products</a>.</li><li>Add many at once from a spreadsheet. See <a href="./../catalog/bulk-upload">Bulk Upload</a>.</li><li>Let Generative AI write the listing. See <a href="./../generative-ai/generate-product-content">Generate Product Content</a>.</li></ul><h2 id="_6-set-stock-and-prices" tabindex="-1">6. Set stock and prices <a class="header-anchor" href="#_6-set-stock-and-prices" aria-label="Permalink to &quot;6. Set stock and prices&quot;">​</a></h2><p>Keep quantities and prices up to date across all your products on one screen. See <a href="./../inventory/manage-inventory">Manage Inventory</a> and <a href="./../pricing/manage-pricing">Manage Pricing</a>.</p><h2 id="_7-submit-for-approval" tabindex="-1">7. Submit for approval <a class="header-anchor" href="#_7-submit-for-approval" aria-label="Permalink to &quot;7. Submit for approval&quot;">​</a></h2><p>Submit each product when it is ready. If the store approves products, it goes on sale once approved. See <a href="./../catalog/product-approval">Product Approval</a>.</p><h2 id="_8-promote-your-shop" tabindex="-1">8. Promote your shop <a class="header-anchor" href="#_8-promote-your-shop" aria-label="Permalink to &quot;8. Promote your shop&quot;">​</a></h2><p>Run discounts on your products, create checkout deals and coupons, and join the store&#39;s own discounts. See <a href="./../marketing/product-discounts">Product Discounts</a> and <a href="./../marketing/checkout-deals">Checkout Deals</a>.</p><h2 id="_9-fulfil-your-orders" tabindex="-1">9. Fulfil your orders <a class="header-anchor" href="#_9-fulfil-your-orders" aria-label="Permalink to &quot;9. Fulfil your orders&quot;">​</a></h2><p>Invoice each order, schedule the pickup, and handle returns. See <a href="./../orders/order-management">Order Management</a> and <a href="./../orders/fulfilment-carriers">Shipments &amp; Carriers</a>.</p><h2 id="_10-get-paid" tabindex="-1">10. Get paid <a class="header-anchor" href="#_10-get-paid" aria-label="Permalink to &quot;10. Get paid&quot;">​</a></h2><p>When an order is complete, request payment for it. The store pays you what you earned, less its commission. See <a href="./../payments/payment-management">Payment Requests &amp; Payouts</a> and <a href="./../payments/transactions">Transactions</a>.</p><h2 id="_11-track-how-you-are-doing" tabindex="-1">11. Track how you are doing <a class="header-anchor" href="#_11-track-how-you-are-doing" aria-label="Permalink to &quot;11. Track how you are doing&quot;">​</a></h2><p>Follow sales on your dashboard, keep your account health good, read reviews and check your reports. See <a href="./../seller-panel/dashboard">Dashboard</a>, <a href="./../sellers/seller-account-health">Account Health</a> and <a href="./../reporting/seller-reporting">Seller Reports</a>.</p>',25)])])}const f=a(s,[["render",n]]);export{h as __pageData,f as default};
